public sealed class Session : IDisposable {
    private int _disposed;
    private readonly Stream _log = File.Create("session.bin");
    public void Dispose() {
        if (Interlocked.Exchange(ref _disposed, 1) != 0) return;  // idempotent
        _log.Dispose();                                           // cascade, owned only
        GC.SuppressFinalize(this);
    }
}
using var session = new Session();   // disposed at end of scope, on every path

