public sealed class Channel : IAsyncDisposable {
    private readonly Socket _socket = new Socket(AddressFamily.InterNetwork,
                                                SocketType.Stream, ProtocolType.Tcp);
    public async ValueTask DisposeAsync() {
        await _socket.DisconnectAsync(false);   // awaited teardown
        _socket.Dispose();                      // synchronous final step
    }
}
